X.append(L('A', 1, 'ابْنُ خَلْدُونَ وَمُقَدِّمَتُهُ', 'İbn Haldûn ve Mukaddime’si', [
 [['وُلِدَ عَبْدُ الرَّحْمَنِ بْنُ خَلْدُونَ فِي تُونُسَ سَنَةَ اثْنَتَيْنِ وَثَلَاثِينَ وَسَبْعِ مِئَةٍ لِلْهِجْرَةِ، لِأُسْرَةٍ أَنْدَلُسِيَّةِ الْأَصْلِ هَاجَرَتْ مِنْ إِشْبِيلِيَةَ.', 'Abdurrahman b. Haldûn hicrî 732 yılında Tunus’ta, İşbîliye’den göç etmiş Endülüs asıllı bir ailede doğdu.'],
  ['وَقَضَى شَطْرًا كَبِيرًا مِنْ حَيَاتِهِ مُتَنَقِّلًا بَيْنَ بَلَاطَاتِ الْمَغْرِبِ وَالْأَنْدَلُسِ، يَتَوَلَّى الْمَنَاصِبَ ثُمَّ يَفْقِدُهَا، وَيَشْهَدُ صُعُودَ الدُّوَلِ وَسُقُوطَهَا عَنْ قُرْبٍ.', 'Hayatının büyük bir kısmını Mağrib ve Endülüs sarayları arasında dolaşarak, makamlara gelip onları kaybederek ve devletlerin yükselişine ve çöküşüne yakından tanıklık ederek geçirdi.'],
  ['ثُمَّ اعْتَزَلَ السِّيَاسَةَ فِي قَلْعَةِ ابْنِ سَلَامَةَ، فَكَتَبَ هُنَاكَ فِي نَحْوِ خَمْسَةِ أَشْهُرٍ مُقَدِّمَةَ تَارِيخِهِ الْكَبِيرِ «كِتَابِ الْعِبَرِ».', 'Sonra Kal‘atü İbn Selâme’de siyasetten çekildi ve orada yaklaşık beş ayda büyük tarihi “Kitâbü’l-İber”in mukaddimesini yazdı.'],
  ['وَقَدْ صَارَتْ هَذِهِ الْمُقَدِّمَةُ أَشْهَرَ مِنَ الْكِتَابِ نَفْسِهِ، حَتَّى إِذَا قِيلَ «الْمُقَدِّمَةُ» انْصَرَفَ الذِّهْنُ إِلَيْهَا.', 'Bu mukaddime kitabın kendisinden daha meşhur oldu; öyle ki “Mukaddime” denince akla o gelir.']],
 [['يَبْدَأُ ابْنُ خَلْدُونَ بِنَقْدِ الْمُؤَرِّخِينَ الَّذِينَ يَقْبَلُونَ الْأَخْبَارَ دُونَ أَنْ يَعْرِضُوهَا عَلَى طَبَائِعِ الْعُمْرَانِ.', 'İbn Haldûn, haberleri umranın (toplumsal hayatın) tabiatına arz etmeden kabul eden tarihçileri eleştirerek başlar.'],
  ['فَالْخَبَرُ عِنْدَهُ لَا يُكْتَفَى فِيهِ بِصِدْقِ النَّاقِلِ، بَلْ لَا بُدَّ أَنْ يُسْأَلَ: هَلْ يُمْكِنُ أَنْ يَقَعَ مِثْلُ هَذَا فِي الْعَادَةِ؟', 'Ona göre bir haberde nakledenin doğruluğuyla yetinilmez; mutlaka şu sorulmalıdır: Böyle bir şey âdeten gerçekleşebilir mi?'],
  ['وَمِنْ أَمْثِلَتِهِ أَعْدَادُ الْجُيُوشِ الْمُبَالَغُ فِيهَا، الَّتِي لَا تَتَّسِعُ لَهَا الْأَرْضُ وَلَا تَكْفِيهَا الْأَرْزَاقُ.', 'Örneklerinden biri, toprağın almayacağı ve rızıkların yetmeyeceği kadar abartılmış ordu sayılarıdır.'],
  ['وَمِنْ هُنَا دَعَا إِلَى عِلْمٍ جَدِيدٍ سَمَّاهُ «عِلْمَ الْعُمْرَانِ»، يَدْرُسُ الِاجْتِمَاعَ الْإِنْسَانِيَّ وَأَحْوَالَهُ، وَرَأَى أَنَّهُ عِلْمٌ لَمْ يُسْبَقْ إِلَيْهِ.', 'Buradan hareketle insan toplumunu ve hâllerini inceleyen, “ilmü’l-umrân” adını verdiği yeni bir ilme çağırdı ve bu ilimde kendisinden önce kimsenin bulunmadığını düşündü.']],
 [['وَمِحْوَرُ هَذَا الْعِلْمِ مَفْهُومُ «الْعَصَبِيَّةِ»، أَيِ الرَّابِطَةِ الَّتِي تَجْمَعُ الْجَمَاعَةَ وَتَدْفَعُهَا إِلَى الْمُطَالَبَةِ بِالْمُلْكِ وَالدِّفَاعِ عَنْهُ.', 'Bu ilmin ekseni “asabiyet” kavramıdır; yani topluluğu bir araya getiren ve onu iktidarı talep etmeye ve savunmaya iten bağ.'],
  ['فَأَهْلُ الْبَادِيَةِ أَشَدُّ عَصَبِيَّةً وَأَقْدَرُ عَلَى الْغَلَبَةِ، فَإِذَا مَلَكُوا انْتَقَلُوا إِلَى الْحَضَارَةِ وَالتَّرَفِ، فَضَعُفَتْ عَصَبِيَّتُهُمْ شَيْئًا فَشَيْئًا.', 'Bedevîler asabiyetçe daha güçlü ve galebe çalmaya daha muktedirdir; iktidara geçince hadarete ve lükse geçerler ve asabiyetleri yavaş yavaş zayıflar.'],
  ['وَلِذَلِكَ شَبَّهَ الدَّوْلَةَ بِالْإِنْسَانِ: لَهَا عُمُرٌ طَبِيعِيٌّ، وَقَدَّرَهُ فِي الْغَالِبِ بِثَلَاثَةِ أَجْيَالٍ، نَحْوَ مِئَةٍ وَعِشْرِينَ سَنَةً.', 'Bu yüzden devleti insana benzetti: Onun da tabii bir ömrü vardır; bunu çoğunlukla üç nesil, yaklaşık yüz yirmi yıl olarak takdir etti.'],
  ['وَمِنْ عَنَاوِينِ فُصُولِهِ الْمَشْهُورَةِ: «فَصْلٌ فِي أَنَّ الظُّلْمَ مُؤْذِنٌ بِخَرَابِ الْعُمْرَانِ»، وَ«فَصْلٌ فِي أَنَّ الْمَغْلُوبَ مُولَعٌ أَبَدًا بِالِاقْتِدَاءِ بِالْغَالِبِ».', 'Meşhur bölüm başlıklarından bazıları şunlardır: “Zulmün umranın yıkılışını haber verdiğine dair bölüm” ve “Mağlubun daima galibi taklide düşkün olduğuna dair bölüm”.']],
 [['وَفِي آخِرِ حَيَاتِهِ اسْتَقَرَّ ابْنُ خَلْدُونَ فِي الْقَاهِرَةِ، فَدَرَّسَ فِيهَا وَتَوَلَّى قَضَاءَ الْمَالِكِيَّةِ مِرَارًا.', 'Ömrünün sonunda İbn Haldûn Kahire’ye yerleşti; orada ders verdi ve birkaç kez Mâlikî kadılığı görevine getirildi.'],
  ['وَحِينَ حَاصَرَ تَيْمُورُ دِمَشْقَ سَنَةَ ثَلَاثٍ وَثَمَانِ مِئَةٍ، الْتَقَى بِهِ وَوَصَفَ لِقَاءَهُ فِي سِيرَتِهِ الذَّاتِيَّةِ وَصْفًا دَقِيقًا.', 'Timur 803 yılında Şam’ı kuşattığında onunla görüştü ve bu görüşmeyi otobiyografisinde ayrıntılı bir şekilde anlattı.'],
  ['وَتُوُفِّيَ فِي الْقَاهِرَةِ سَنَةَ ثَمَانٍ وَثَمَانِ مِئَةٍ، وَلَمْ تَنَلْ أَفْكَارُهُ فِي عَصْرِهِ مَا تَسْتَحِقُّهُ مِنَ الْعِنَايَةِ.', 'Kahire’de 808 yılında vefat etti; fikirleri kendi çağında hak ettiği ilgiyi görmedi.'],
  ['غَيْرَ أَنَّ الْعُثْمَانِيِّينَ الْتَفَتُوا إِلَيْهَا مُبَكِّرًا، فَتَرْجَمَ بِيرِي زَادَهْ جُزْءًا كَبِيرًا مِنَ الْمُقَدِّمَةِ إِلَى التُّرْكِيَّةِ، ثُمَّ أَتَمَّ أَحْمَد جَوْدَتْ بَاشَا تَرْجَمَتَهَا.', 'Ancak Osmanlılar onlara erkenden ilgi gösterdi; Pîrîzâde Mukaddime’nin büyük bir kısmını Türkçeye çevirdi, sonra Ahmed Cevdet Paşa tercümeyi tamamladı.']]],
 [V('بَلَاطٌ (ج. بَلَاطَاتٌ)', 'saray (hükümdar sarayı)', 'عَمِلَ فِي بَلَاطِ السُّلْطَانِ كَاتِبًا.', 'Sultanın sarayında kâtip olarak çalıştı.'),
  V('اعْتَزَلَ', 'çekildi, uzak durdu', 'اعْتَزَلَ النَّاسَ لِيَكْتُبَ كِتَابَهُ.', 'Kitabını yazmak için insanlardan uzaklaştı.'),
  V('الْعُمْرَانُ', 'umran, toplumsal hayat, medeniyet', 'دَرَسَ ابْنُ خَلْدُونَ طَبَائِعَ الْعُمْرَانِ.', 'İbn Haldûn umranın tabiatını inceledi.'),
  V('الْعَصَبِيَّةُ', 'asabiyet, grup dayanışması', 'تَضْعُفُ الْعَصَبِيَّةُ مَعَ التَّرَفِ.', 'Asabiyet lüksle birlikte zayıflar.'),
  V('التَّرَفُ', 'lüks, refah içinde yaşama', 'أَفْسَدَ التَّرَفُ أَخْلَاقَ الْأُمَرَاءِ.', 'Lüks, emirlerin ahlakını bozdu.'),
  V('مُؤْذِنٌ بِـ', '-in habercisi, -i haber veren', 'الظُّلْمُ مُؤْذِنٌ بِخَرَابِ الْعُمْرَانِ.', 'Zulüm, umranın yıkılışının habercisidir.'),
  V('مُولَعٌ بِـ', 'düşkün, tutkun', 'الْمَغْلُوبُ مُولَعٌ بِتَقْلِيدِ الْغَالِبِ.', 'Mağlup, galibi taklide düşkündür.'),
  V('الْمُبَالَغُ فِيهِ', 'abartılmış', 'هَذَا رَقَمٌ مُبَالَغٌ فِيهِ.', 'Bu abartılmış bir rakam.')],
 [['İbn Haldûn’un ailesi aslen nereliydi?', ['Mısır', 'Endülüs (İşbîliye)', 'Bağdat', 'Fas (Fes)'], 1],
  ['İbn Haldûn’a göre bir haberin kabulünde ne gereklidir?', ['Yalnız ravinin doğruluğu', 'Haberin umranın tabiatına ve âdete uygunluğu', 'Haberin eski olması', 'Haberin şiirle desteklenmesi'], 1],
  ['İbn Haldûn bir devletin tabii ömrünü genellikle ne kadar takdir eder?', ['Bir nesil', 'Üç nesil, yaklaşık 120 yıl', 'Beş yüz yıl', 'Sınırsız'], 1],
  ['Mukaddime’nin Türkçe tercümesini tamamlayan kimdir?', ['Kâtib Çelebi', 'Pîrîzâde', 'Ahmed Cevdet Paşa', 'Nâimâ'], 2]]))

X.append(L('I', 5, 'الْأَنْدَلُسُ: حَضَارَةٌ عَلَى ضِفَافِ الْوَادِي الْكَبِيرِ', 'Endülüs: Vâdilkebîr kıyısında bir medeniyet', [
 [['عَبَرَ طَارِقُ بْنُ زِيَادٍ الْمَضِيقَ إِلَى شِبْهِ الْجَزِيرَةِ الْإِيبِيرِيَّةِ سَنَةَ اثْنَتَيْنِ وَتِسْعِينَ لِلْهِجْرَةِ، فَبَدَأَ فَصْلٌ مِنَ التَّارِيخِ دَامَ نَحْوَ ثَمَانِيَةِ قُرُونٍ.', 'Târık b. Ziyâd hicrî 92 yılında boğazı geçerek İber Yarımadası’na girdi ve yaklaşık sekiz asır süren bir tarih faslı başladı.'],
  ['وَبَعْدَ سُقُوطِ الدَّوْلَةِ الْأُمَوِيَّةِ فِي الْمَشْرِقِ، نَجَا عَبْدُ الرَّحْمَنِ الدَّاخِلُ مِنْ بَطْشِ الْعَبَّاسِيِّينَ، وَأَسَّسَ فِي قُرْطُبَةَ إِمَارَةً أُمَوِيَّةً مُسْتَقِلَّةً.', 'Doğudaki Emevî devleti yıkıldıktan sonra Abdurrahman ed-Dâhil Abbâsîlerin şiddetinden kurtuldu ve Kurtuba’da bağımsız bir Emevî emirliği kurdu.'],
  ['ثُمَّ أَعْلَنَ حَفِيدُهُ عَبْدُ الرَّحْمَنِ النَّاصِرُ الْخِلَافَةَ سَنَةَ سِتَّ عَشْرَةَ وَثَلَاثِ مِئَةٍ، فَصَارَتْ قُرْطُبَةُ تُنَافِسُ بَغْدَادَ وَالْقَاهِرَةَ.', 'Sonra torunu Abdurrahman en-Nâsır 316 yılında hilafeti ilan etti ve Kurtuba, Bağdat ve Kahire ile yarışır oldu.'],
  ['وَيُرْوَى أَنَّ مَكْتَبَةَ الْخَلِيفَةِ الْحَكَمِ الْمُسْتَنْصِرِ ضَمَّتْ نَحْوَ أَرْبَعِ مِئَةِ أَلْفِ مُجَلَّدٍ، وَإِنْ كَانَ بَعْضُ الْبَاحِثِينَ يَرَوْنَ فِي هَذَا الرَّقَمِ مُبَالَغَةً.', 'Halife Hakem el-Müstansır’ın kütüphanesinin yaklaşık dört yüz bin cilt içerdiği rivayet edilir; gerçi bazı araştırmacılar bu rakamda abartı görür.']],
 [['وَمِنْ أَبْرَزِ شَوَاهِدِ تِلْكَ الْحَضَارَةِ جَامِعُ قُرْطُبَةَ، الَّذِي بَدَأَ بِنَاءَهُ عَبْدُ الرَّحْمَنِ الدَّاخِلُ، ثُمَّ وَسَّعَهُ مَنْ جَاءَ بَعْدَهُ مَرَّةً بَعْدَ مَرَّةٍ.', 'O medeniyetin en göze çarpan şahitlerinden biri, inşasına Abdurrahman ed-Dâhil’in başladığı ve ondan sonra gelenlerin defalarca genişlettiği Kurtuba Camii’dir.'],
  ['وَيَدْخُلُ الزَّائِرُ الْيَوْمَ غَابَةً مِنَ الْأَعْمِدَةِ تَعْلُوهَا أَقْوَاسٌ مُزْدَوَجَةٌ بِلَوْنَيْنِ أَحْمَرَ وَأَبْيَضَ، فَيَشْعُرُ أَنَّ الْمَكَانَ لَا نِهَايَةَ لَهُ.', 'Bugünün ziyaretçisi, üzerinde kırmızı ve beyaz iki renkli çift kemerler yükselen bir sütun ormanına girer ve mekânın sonu yokmuş gibi hisseder.'],
  ['وَلَمْ تَكُنِ الْحَضَارَةُ الْأَنْدَلُسِيَّةُ عُمْرَانًا فَحَسْبُ، بَلْ كَانَتْ ذَوْقًا فِي الْعَيْشِ؛ فَيُنْسَبُ إِلَى زِرْيَابَ الْقَادِمِ مِنْ بَغْدَادَ أَنَّهُ عَلَّمَ النَّاسَ تَرْتِيبَ الطَّعَامِ وَأَلْوَانَ اللِّبَاسِ بِحَسَبِ الْفُصُولِ.', 'Endülüs medeniyeti yalnızca imar değil, bir yaşama zevkiydi; Bağdat’tan gelen Ziryâb’a, insanlara yemek sırasını ve mevsimlere göre giyim renklerini öğrettiği nispet edilir.'],
  ['وَعَاشَ فِي مُدُنِهَا مُسْلِمُونَ وَنَصَارَى وَيَهُودٌ، تَبَادَلُوا الْمَعَارِفَ وَالْحِرَفَ، وَإِنْ لَمْ يَخْلُ ذَلِكَ التَّعَايُشُ مِنْ تَوَتُّرٍ وَصِرَاعٍ فِي بَعْضِ الْأَحْيَانِ.', 'Şehirlerinde Müslümanlar, Hristiyanlar ve Yahudiler yaşadı; bilgi ve zanaatlarını paylaştılar; gerçi bu bir arada yaşama zaman zaman gerilim ve çatışmadan uzak değildi.']],
 [['وَقَدْ أَنْجَبَتِ الْأَنْدَلُسُ عُلَمَاءَ كِبَارًا فِي كُلِّ فَنٍّ؛ فَمِنْهُمُ ابْنُ حَزْمٍ الْفَقِيهُ الظَّاهِرِيُّ صَاحِبُ «طَوْقِ الْحَمَامَةِ».', 'Endülüs her alanda büyük âlimler yetiştirdi; bunlardan biri “Tavku’l-hamâme”nin sahibi Zâhirî fakih İbn Hazm’dır.'],
  ['وَمِنْهُمُ ابْنُ رُشْدٍ الْقُرْطُبِيُّ، الَّذِي جَمَعَ بَيْنَ الْقَضَاءِ وَالطِّبِّ وَالْفَلْسَفَةِ، وَشَرَحَ كُتُبَ أَرِسْطُو شَرْحًا جَعَلَ الْأُورُوبِّيِّينَ يُلَقِّبُونَهُ بِـ«الشَّارِحِ».', 'Bir diğeri, kadılık, tıp ve felsefeyi bir araya getiren ve Aristo’nun kitaplarını öyle şerh etti ki Avrupalıların ona “Şârih” lakabını verdiği Kurtubalı İbn Rüşd’dür.'],
  ['وَبَعْدَ سُقُوطِ الْخِلَافَةِ تَفَرَّقَتِ الْأَنْدَلُسُ إِلَى دُوَيْلَاتٍ عُرِفَتْ بِمُلُوكِ الطَّوَائِفِ، فَتَنَافَسَتْ فِي رِعَايَةِ الشُّعَرَاءِ وَضَعُفَتْ أَمَامَ أَعْدَائِهَا.', 'Hilafet yıkıldıktan sonra Endülüs, Mülûkü’t-tavâif diye bilinen küçük devletlere bölündü; bunlar şairleri himayede yarıştılar ve düşmanları karşısında zayıfladılar.'],
  ['وَفِي ذَلِكَ رَثَى أَبُو الْبَقَاءِ الرُّنْدِيُّ مُدُنَهَا الضَّائِعَةَ بِقَصِيدَتِهِ الَّتِي مَطْلَعُهَا: «لِكُلِّ شَيْءٍ إِذَا مَا تَمَّ نُقْصَانُ ... فَلَا يُغَرَّ بِطِيبِ الْعَيْشِ إِنْسَانُ».', 'Bu konuda Ebü’l-Bekâ er-Rundî kaybedilen şehirlerine şu beyitle başlayan kasidesiyle ağıt yaktı: “Her şey tamam olunca eksilmeye başlar; o hâlde hiç kimse hayatın tatlılığına aldanmasın.”']],
 [['وَكَانَتْ غَرْنَاطَةُ آخِرَ مَعَاقِلِ الْمُسْلِمِينَ، حَكَمَهَا بَنُو نَصْرٍ قَرْنَيْنِ وَنِصْفًا، وَبَنَوْا فِيهَا قَصْرَ الْحَمْرَاءِ.', 'Gırnata Müslümanların son kalesiydi; Nasrîler iki buçuk asır orada hüküm sürdüler ve Elhamra Sarayı’nı inşa ettiler.'],
  ['وَلَا تَزَالُ جُدْرَانُ الْحَمْرَاءِ تَحْمِلُ عِبَارَةَ «لَا غَالِبَ إِلَّا اللَّهُ» مَنْقُوشَةً مِئَاتِ الْمَرَّاتِ، شِعَارًا لِتِلْكَ الدَّوْلَةِ.', 'Elhamra’nın duvarları, o devletin şiarı olarak yüzlerce kez nakşedilmiş “Allah’tan başka galip yoktur” ibaresini hâlâ taşır.'],
  ['ثُمَّ سَلَّمَهَا آخِرُ مُلُوكِهَا أَبُو عَبْدِ اللَّهِ الصَّغِيرُ سَنَةَ سَبْعٍ وَتِسْعِينَ وَثَمَانِ مِئَةٍ، الْمُوَافِقَةِ لِسَنَةِ أَلْفٍ وَأَرْبَعِ مِئَةٍ وَاثْنَتَيْنِ وَتِسْعِينَ لِلْمِيلَادِ.', 'Sonra son hükümdarı Ebû Abdullah es-Sağîr onu miladi 1492’ye denk gelen 897 yılında teslim etti.'],
  ['وَهَكَذَا انْتَهَى الْوُجُودُ السِّيَاسِيُّ لِلْمُسْلِمِينَ فِي الْأَنْدَلُسِ، لَكِنَّ أَثَرَهُمْ بَقِيَ فِي الْعِمَارَةِ وَاللُّغَةِ وَالْمُوسِيقَى، بَلْ فِي آلَافِ الْكَلِمَاتِ الْإِسْبَانِيَّةِ ذَاتِ الْأَصْلِ الْعَرَبِيِّ.', 'Böylece Müslümanların Endülüs’teki siyasi varlığı sona erdi; ama izleri mimaride, dilde ve musikide, hatta Arapça kökenli binlerce İspanyolca kelimede kaldı.']]],
 [V('الْمَضِيقُ', 'boğaz', 'عَبَرَ الْجَيْشُ الْمَضِيقَ لَيْلًا.', 'Ordu boğazı gece geçti.'),
  V('بَطْشٌ', 'şiddet, zorbalık', 'هَرَبَ الْأَمِيرُ مِنْ بَطْشِ أَعْدَائِهِ.', 'Emir düşmanlarının şiddetinden kaçtı.'),
  V('نَافَسَ – يُنَافِسُ', 'rekabet etti, yarıştı', 'كَانَتْ قُرْطُبَةُ تُنَافِسُ بَغْدَادَ.', 'Kurtuba Bağdat’la yarışıyordu.'),
  V('مُجَلَّدٌ', 'cilt (kitap)', 'يَقَعُ الْكِتَابُ فِي عَشَرَةِ مُجَلَّدَاتٍ.', 'Kitap on ciltten oluşur.'),
  V('التَّعَايُشُ', 'bir arada yaşama', 'التَّعَايُشُ يَحْتَاجُ إِلَى الْعَدْلِ.', 'Bir arada yaşama adalete muhtaçtır.'),
  V('رَثَى – يَرْثِي', 'mersiye yazdı, ağıt yaktı', 'رَثَى الشَّاعِرُ مَدِينَتَهُ الضَّائِعَةَ.', 'Şair kaybettiği şehrine ağıt yaktı.'),
  V('مَعْقِلٌ (ج. مَعَاقِلُ)', 'kale, sığınak', 'كَانَتْ غَرْنَاطَةُ آخِرَ الْمَعَاقِلِ.', 'Gırnata son kaleydi.'),
  V('مَنْقُوشٌ', 'nakşedilmiş, oyulmuş', 'رَأَيْتُ آيَةً مَنْقُوشَةً عَلَى الْجِدَارِ.', 'Duvara nakşedilmiş bir âyet gördüm.')],
 [['Endülüs’te bağımsız Emevî emirliğini kim kurdu?', ['Târık b. Ziyâd', 'Abdurrahman ed-Dâhil', 'Hakem el-Müstansır', 'Ebû Abdullah es-Sağîr'], 1],
  ['Metne göre Hakem’in kütüphanesindeki cilt sayısı hakkında ne söylenir?', ['Kesin olarak 400 bindir', 'Bazı araştırmacılar rakamda abartı görür', 'Hiç kitap yoktu', 'Hepsi Bağdat’a taşındı'], 1],
  ['Avrupalıların İbn Rüşd’e verdiği lakap nedir?', ['Muallim-i Evvel', 'Şârih', 'Hüccetü’l-İslâm', 'Şeyhü’r-reîs'], 1],
  ['Elhamra duvarlarında tekrar edilen ibare hangisidir?', ['Lâ ilâhe illallah', 'Lâ gâlibe illallah', 'el-Mülkü lillâh', 'Bismillah'], 1]]))

X.append(L('I', 7, 'تَدْوِينُ اللُّغَةِ الْعَرَبِيَّةِ: الْخَلِيلُ وَسِيبَوَيْهِ', 'Arap dilinin tedvini: Halîl ve Sîbeveyh', [
 [['لَمَّا اتَّسَعَتِ الْفُتُوحُ وَدَخَلَ فِي الْإِسْلَامِ أَقْوَامٌ لَا يَتَكَلَّمُونَ الْعَرَبِيَّةَ، بَدَأَ اللَّحْنُ يَتَسَرَّبُ إِلَى الْأَلْسِنَةِ، حَتَّى خِيفَ عَلَى قِرَاءَةِ الْقُرْآنِ نَفْسِهَا.', 'Fetihler genişleyip Arapça konuşmayan kavimler İslâm’a girince dillere lahn (dil hatası) sızmaya başladı; öyle ki Kur’an kıraatinin kendisi için bile endişe edildi.'],
  ['وَتَنْسُبُ الرِّوَايَاتُ إِلَى أَبِي الْأَسْوَدِ الدُّؤَلِيِّ أَنَّهُ أَوَّلُ مَنْ وَضَعَ أُصُولَ النَّحْوِ، وَأَنَّهُ ضَبَطَ أَوَاخِرَ الْكَلِمَاتِ فِي الْمُصْحَفِ بِنُقَطٍ مُلَوَّنَةٍ.', 'Rivayetler, nahvin esaslarını ilk koyanın ve mushafta kelime sonlarını renkli noktalarla zabtedenin Ebü’l-Esved ed-Düelî olduğunu söyler.'],
  ['غَيْرَ أَنَّ هَذِهِ الْبِدَايَاتِ ظَلَّتْ مُتَفَرِّقَةً، حَتَّى جَاءَ جِيلٌ مِنْ عُلَمَاءِ الْبَصْرَةِ حَوَّلَ الْمُلَاحَظَاتِ إِلَى عِلْمٍ مُنَظَّمٍ.', 'Ne var ki bu başlangıçlar dağınık kaldı; ta ki Basra âlimlerinden bir nesil gelip gözlemleri düzenli bir ilme dönüştürene kadar.'],
  ['وَكَانَ مَصْدَرُهُمُ الْأَوَّلُ بَعْدَ الْقُرْآنِ كَلَامَ الْأَعْرَابِ، فَكَانُوا يَخْرُجُونَ إِلَى الْبَادِيَةِ وَيُقِيمُونَ بَيْنَ الْقَبَائِلِ الْفَصِيحَةِ لِيَسْمَعُوا اللُّغَةَ مِنْ أَهْلِهَا.', 'Kur’an’dan sonra ilk kaynakları bedevîlerin konuşmasıydı; dili ehlinden duymak için çöle çıkar ve fasih kabileler arasında kalırlardı.']],
 [['وَفِي مُقَدِّمَةِ هَذَا الْجِيلِ الْخَلِيلُ بْنُ أَحْمَدَ الْفَرَاهِيدِيُّ، الَّذِي يُعَدُّ مِنْ أَذْكَى الْعُقُولِ فِي تَارِيخِ الْعَرَبِيَّةِ.', 'Bu neslin başında, Arapça tarihinin en zeki akıllarından sayılan Halîl b. Ahmed el-Ferâhîdî gelir.'],
  ['فَهُوَ الَّذِي وَضَعَ عَلَامَاتِ الْحَرَكَاتِ الَّتِي نَسْتَعْمِلُهَا الْيَوْمَ، فَجَعَلَ الْفَتْحَةَ أَلِفًا صَغِيرَةً مُضْطَجِعَةً، وَالضَّمَّةَ وَاوًا صَغِيرَةً، وَالْكَسْرَةَ يَاءً صَغِيرَةً تَحْتَ الْحَرْفِ.', 'Bugün kullandığımız hareke işaretlerini koyan odur: Fethayı yatık küçük bir elif, dammeyi küçük bir vav, kesrayı da harfin altında küçük bir yâ yaptı.'],
  ['وَهُوَ الَّذِي اسْتَنْبَطَ عِلْمَ الْعَرُوضِ، فَحَصَرَ أَوْزَانَ الشِّعْرِ الْعَرَبِيِّ فِي خَمْسَةَ عَشَرَ بَحْرًا، ثُمَّ زَادَ تِلْمِيذُهُ الْأَخْفَشُ بَحْرًا سَادِسَ عَشَرَ.', 'Arûz ilmini ortaya çıkaran da odur; Arap şiirinin vezinlerini on beş bahirde topladı, sonra talebesi Ahfeş on altıncı bir bahir ekledi.'],
  ['ثُمَّ أَلَّفَ «كِتَابَ الْعَيْنِ»، أَوَّلَ مُعْجَمٍ فِي الْعَرَبِيَّةِ، وَرَتَّبَهُ عَلَى مَخَارِجِ الْحُرُوفِ مُبْتَدِئًا بِأَبْعَدِهَا فِي الْحَلْقِ، وَهُوَ حَرْفُ الْعَيْنِ.', 'Sonra Arapçanın ilk sözlüğü olan “Kitâbü’l-Ayn”ı yazdı ve onu boğazda en derinde olan harf, yani ayn harfinden başlayarak harflerin mahreçlerine göre düzenledi.']],
 [['وَمِنْ تَلَامِيذِ الْخَلِيلِ شَابٌّ فَارِسِيُّ الْأَصْلِ اسْمُهُ عَمْرُو بْنُ عُثْمَانَ، وَلَقَبُهُ سِيبَوَيْهِ.', 'Halîl’in talebelerinden biri, Amr b. Osman adında Fars asıllı bir gençti; lakabı Sîbeveyh idi.'],
  ['جَمَعَ سِيبَوَيْهِ عِلْمَ شُيُوخِهِ وَأَضَافَ إِلَيْهِ تَحْلِيلَهُ الدَّقِيقَ، فِي كِتَابٍ لَمْ يُسَمِّهِ، فَعُرِفَ بَيْنَ النَّاسِ بِـ«الْكِتَابِ».', 'Sîbeveyh hocalarının ilmini topladı ve ona kendi ince tahlilini ekledi; bunu ad koymadığı bir kitapta yaptı ve bu kitap insanlar arasında “el-Kitâb” diye tanındı.'],
  ['وَبَلَغَ مِنْ مَنْزِلَتِهِ أَنَّ النُّحَاةَ سَمَّوْهُ «قُرْآنَ النَّحْوِ»، وَكَانَ يُقَالُ لِمَنْ أَرَادَ أَنْ يَقْرَأَهُ: هَلْ رَكِبْتَ الْبَحْرَ؟ تَعْظِيمًا لَهُ وَاسْتِصْعَابًا.', 'Kitabın değeri o dereceye ulaştı ki nahivciler ona “nahvin Kur’an’ı” dediler; onu okumak isteyene, ona duyulan saygıdan ve onu zor bulmaktan ötürü “Denize mi açıldın?” denirdi.'],
  ['وَمِنْ أَشْهَرِ أَخْبَارِهِ مُنَاظَرَتُهُ لِلْكِسَائِيِّ إِمَامِ الْكُوفِيِّينَ فِي بَغْدَادَ، فِيمَا يُعْرَفُ بِـ«الْمَسْأَلَةِ الزُّنْبُورِيَّةِ».', 'En meşhur haberlerinden biri, Bağdat’ta Kûfelilerin imamı Kisâî ile yaptığı ve “ez-Zünbûriyye meselesi” diye bilinen münazaradır.']],
 [['وَكَانَ السُّؤَالُ: أَيُقَالُ «فَإِذَا هُوَ هِيَ» أَمْ «فَإِذَا هُوَ إِيَّاهَا»؟ فَأَجَازَ الْكِسَائِيُّ النَّصْبَ، وَمَنَعَهُ سِيبَوَيْهِ.', 'Soru şuydu: “Fe-izâ huve hiye” mi denir, yoksa “fe-izâ huve iyyâhâ” mı? Kisâî nasbı caiz gördü, Sîbeveyh ise reddetti.'],
  ['وَتَذْكُرُ الرِّوَايَاتُ أَنَّ الْحُكْمَ صَدَرَ لِصَالِحِ الْكِسَائِيِّ، فَخَرَجَ سِيبَوَيْهِ مِنْ بَغْدَادَ حَزِينًا، وَلَمْ يَلْبَثْ أَنْ تُوُفِّيَ شَابًّا.', 'Rivayetler hükmün Kisâî lehine çıktığını, Sîbeveyh’in Bağdat’tan üzgün ayrıldığını ve çok geçmeden genç yaşta vefat ettiğini anlatır.'],
  ['وَتَكْشِفُ هَذِهِ الْمُنَاظَرَةُ عَنِ اخْتِلَافِ مَنْهَجَيْنِ: مَنْهَجِ الْبَصْرِيِّينَ الَّذِينَ يَطْرُدُونَ الْقِيَاسَ، وَمَنْهَجِ الْكُوفِيِّينَ الَّذِينَ يَتَوَسَّعُونَ فِي قَبُولِ الْمَسْمُوعِ.', 'Bu münazara iki yöntemin farkını ortaya koyar: Kıyası tutarlı biçimde uygulayan Basralıların yöntemi ile duyulanı kabulde geniş davranan Kûfelilerin yöntemi.'],
  ['وَبِفَضْلِ هَذَا الْجِيلِ حُفِظَتِ الْعَرَبِيَّةُ مِنَ الضَّيَاعِ، وَصَارَ مِنَ الْمُمْكِنِ أَنْ يَتَعَلَّمَهَا مَنْ لَمْ يَنْشَأْ فِي الْبَادِيَةِ، كَمَا نَتَعَلَّمُهَا نَحْنُ الْيَوْمَ.', 'Bu nesil sayesinde Arapça kaybolmaktan korundu ve onu, tıpkı bugün bizim öğrendiğimiz gibi, çölde yetişmemiş birinin öğrenmesi mümkün hâle geldi.']]],
 [V('اللَّحْنُ', 'lahn, dil (i‘râb) hatası', 'كَانَ اللَّحْنُ فِي الْقُرْآنِ عَيْبًا كَبِيرًا.', 'Kur’an’da lahn büyük bir kusurdu.'),
  V('تَسَرَّبَ – يَتَسَرَّبُ', 'sızdı', 'تَسَرَّبَ الْمَاءُ إِلَى الْبَيْتِ.', 'Su eve sızdı.'),
  V('ضَبَطَ', 'zabtetti, harekeledi', 'ضَبَطَ الْكَاتِبُ النَّصَّ بِالشَّكْلِ.', 'Kâtip metni harekeyle zabtetti.'),
  V('اسْتَنْبَطَ', 'ortaya çıkardı, istinbat etti', 'اسْتَنْبَطَ الْخَلِيلُ أَوْزَانَ الشِّعْرِ.', 'Halîl şiir vezinlerini ortaya çıkardı.'),
  V('مُعْجَمٌ (ج. مَعَاجِمُ)', 'sözlük', 'رَتَّبَ الْمُعْجَمَ عَلَى الْمَخَارِجِ.', 'Sözlüğü mahreçlere göre düzenledi.'),
  V('مَخْرَجٌ (ج. مَخَارِجُ)', 'mahreç, harfin çıkış yeri', 'الْعَيْنُ مِنْ أَبْعَدِ الْمَخَارِجِ.', 'Ayn en derin mahreçlerdendir.'),
  V('مُنَاظَرَةٌ', 'münazara, ilmî tartışma', 'جَرَتْ بَيْنَهُمَا مُنَاظَرَةٌ مَشْهُورَةٌ.', 'Aralarında meşhur bir münazara geçti.'),
  V('طَرَدَ الْقِيَاسَ', 'kıyası tutarlı uyguladı', 'كَانَ الْبَصْرِيُّونَ يَطْرُدُونَ الْقِيَاسَ.', 'Basralılar kıyası tutarlı biçimde uygulardı.')],
 [['Bugünkü hareke işaretlerini (fetha, damme, kesra) kim koymuştur?', ['Ebü’l-Esved ed-Düelî', 'Halîl b. Ahmed', 'Sîbeveyh', 'Kisâî'], 1],
  ['“Kitâbü’l-Ayn” neye göre düzenlenmiştir?', ['Alfabe sırasına', 'Harflerin mahreçlerine', 'Konulara', 'Kelimelerin son harfine'], 1],
  ['Sîbeveyh’in eserine nahivciler hangi unvanı vermiştir?', ['Nahvin anahtarı', 'Nahvin Kur’an’ı', 'Nahvin denizi', 'Nahvin özü'], 1],
  ['Metne göre Basralıların yöntemi nedir?', ['Duyulan her şeyi kabul etmek', 'Kıyası tutarlı biçimde uygulamak', 'Şiiri reddetmek', 'Yalnız Kur’an’a dayanmak'], 1]]))

X.append(L('I', 7, 'الْجَاحِظُ: أَدِيبُ الْعَقْلِ وَالسُّخْرِيَةِ', 'Câhiz: Aklın ve ironinin edibi', [
 [['وُلِدَ أَبُو عُثْمَانَ عَمْرُو بْنُ بَحْرٍ فِي الْبَصْرَةِ، وَلُقِّبَ بِـ«الْجَاحِظِ» لِجُحُوظٍ ظَاهِرٍ فِي عَيْنَيْهِ.', 'Ebû Osman Amr b. Bahr Basra’da doğdu; gözlerindeki belirgin pörtleklik yüzünden “Câhiz” lakabını aldı.'],
  ['نَشَأَ فَقِيرًا، وَتَذْكُرُ كُتُبُ التَّرَاجِمِ أَنَّهُ كَانَ يَكْتَرِي دَكَاكِينَ الْوَرَّاقِينَ لَيْلًا، فَيَبِيتُ فِيهَا يَقْرَأُ مَا فِيهَا مِنَ الْكُتُبِ.', 'Fakir olarak yetişti; biyografi kitapları onun geceleri kitapçı dükkânlarını kiralayıp içlerindeki kitapları okuyarak sabahladığını anlatır.'],
  ['وَتَتَلْمَذَ عَلَى إِبْرَاهِيمَ النَّظَّامِ مِنْ أَئِمَّةِ الْمُعْتَزِلَةِ، فَغَلَبَ عَلَى تَفْكِيرِهِ الِاحْتِكَامُ إِلَى الْعَقْلِ وَالشَّكُّ الْمَنْهَجِيُّ.', 'Mu‘tezile imamlarından İbrâhîm en-Nazzâm’ın talebesi oldu; bu yüzden düşüncesine akla başvurma ve yöntemli şüphe hâkim oldu.'],
  ['وَعَاشَ عُمُرًا طَوِيلًا تَجَاوَزَ التِّسْعِينَ عَلَى أَرْجَحِ الْأَقْوَالِ، وَتُوُفِّيَ سَنَةَ خَمْسٍ وَخَمْسِينَ وَمِئَتَيْنِ، فَشَهِدَ عُهُودَ عَدَدٍ مِنَ الْخُلَفَاءِ الْعَبَّاسِيِّينَ.', 'En kuvvetli görüşe göre doksanı aşan uzun bir ömür yaşadı ve 255 yılında vefat etti; böylece birçok Abbâsî halifesinin devrine tanık oldu.']],
 [['تَرَكَ الْجَاحِظُ مُؤَلَّفَاتٍ كَثِيرَةً، أَشْهَرُهَا «الْبَيَانُ وَالتَّبْيِينُ» وَ«الْحَيَوَانُ» وَ«الْبُخَلَاءُ».', 'Câhiz pek çok eser bıraktı; en meşhurları “el-Beyân ve’t-tebyîn”, “el-Hayevân” ve “el-Buhalâ”dır.'],
  ['وَفِي «الْبَيَانِ وَالتَّبْيِينِ» عَرَّفَ الْبَيَانَ بِأَنَّهُ «اسْمٌ جَامِعٌ لِكُلِّ شَيْءٍ كَشَفَ لَكَ قِنَاعَ الْمَعْنَى»، فَلَمْ يَقْصُرْهُ عَلَى الْكَلَامِ وَحْدَهُ.', '“el-Beyân ve’t-tebyîn”de beyânı “sana anlamın peçesini açan her şeyin ortak adı” diye tanımladı; onu yalnızca sözle sınırlamadı.'],
  ['أَمَّا «الْحَيَوَانُ» فَمَوْسُوعَةٌ ضَخْمَةٌ يَمْزُجُ فِيهَا الْمُشَاهَدَةَ وَالتَّجْرِبَةَ بِالشِّعْرِ وَالْحَدِيثِ وَالنَّوَادِرِ، فَيَنْتَقِلُ بِالْقَارِئِ مِنَ الْبَعُوضِ إِلَى الْفَلْسَفَةِ.', '“el-Hayevân” ise gözlem ve deneyi şiir, hadis ve nüktelerle harmanladığı devasa bir ansiklopedidir; okuru sivrisinekten felsefeye götürür.'],
  ['وَفِيهِ قَوْلُهُ الشَّهِيرُ: «الْمَعَانِي مَطْرُوحَةٌ فِي الطَّرِيقِ... وَإِنَّمَا الشَّأْنُ فِي إِقَامَةِ الْوَزْنِ وَتَخَيُّرِ اللَّفْظِ»، وَهِيَ عِبَارَةٌ شَغَلَتِ النُّقَّادَ قُرُونًا.', 'Orada şu meşhur sözü yer alır: “Anlamlar yolda atılmış durur… asıl mesele vezni kurmak ve lafzı seçmektir”; bu ifade eleştirmenleri asırlarca meşgul etti.']],
 [['وَفِي «الْبُخَلَاءِ» يَرْسُمُ صُوَرًا سَاخِرَةً لِبُخَلَاءِ عَصْرِهِ، يُورِدُ حُجَجَهُمْ بِأَلْسِنَتِهِمْ، فَيَضْحَكُ الْقَارِئُ مِنْهُمْ وَهُوَ يَكَادُ يَقْتَنِعُ بِمَنْطِقِهِمْ.', '“el-Buhalâ”da devrinin cimrilerinin alaycı portrelerini çizer; onların delillerini kendi dilleriyle aktarır, okur da onların mantığına neredeyse ikna olurken onlara güler.'],
  ['وَمِنْ أَبْرَزِ خَصَائِصِ أُسْلُوبِهِ الِاسْتِطْرَادُ؛ إِذْ يَخْرُجُ مِنْ مَوْضُوعٍ إِلَى آخَرَ، ثُمَّ يَعُودُ، وَيُصَرِّحُ بِأَنَّهُ يَفْعَلُ ذَلِكَ دَفْعًا لِلْمَلَلِ عَنِ الْقَارِئِ.', 'Üslubunun en belirgin özelliklerinden biri istitrattır (konu dışına çıkma); bir konudan diğerine geçer, sonra geri döner ve bunu okurdan usancı gidermek için yaptığını açıkça söyler.'],
  ['وَجُمَلُهُ طَوِيلَةٌ مُتَوَازِنَةٌ، تَكْثُرُ فِيهَا الْمُتَرَادِفَاتُ وَالْمُقَابَلَاتُ، لَكِنَّهَا لَا تَفْقِدُ وُضُوحَهَا وَلَا حَيَوِيَّتَهَا.', 'Cümleleri uzun ve dengelidir; eşanlamlılar ve karşıtlıklar çoktur, ama ne açıklığını ne de canlılığını kaybeder.'],
  ['وَلِهَذَا عَدَّهُ النُّقَّادُ إِمَامَ النَّثْرِ الْعَرَبِيِّ، وَيُنْسَبُ إِلَى ابْنِ الْعَمِيدِ قَوْلُهُ: «كُتُبُ الْجَاحِظِ تُعَلِّمُ الْعَقْلَ أَوَّلًا وَالْأَدَبَ ثَانِيًا».', 'Bu yüzden eleştirmenler onu Arap nesrinin imamı saydı; İbnü’l-Amîd’e şu söz nispet edilir: “Câhiz’in kitapları önce aklı, sonra edebi öğretir.”']],
 [['وَمِنَ الطَّرِيفِ أَنَّ الْمَوْتَ نَفْسَهُ جَاءَهُ فِي صُورَةٍ تُشْبِهُ حَيَاتَهُ؛ إِذْ يُرْوَى أَنَّهُ مَاتَ تَحْتَ كُتُبٍ سَقَطَتْ عَلَيْهِ وَهُوَ شَيْخٌ مَفْلُوجٌ.', 'İlginçtir ki ölüm bile ona hayatına benzer bir şekilde geldi; felçli bir ihtiyarken üzerine düşen kitapların altında öldüğü rivayet edilir.'],
  ['وَسَوَاءٌ صَحَّتْ هَذِهِ الرِّوَايَةُ أَمْ لَمْ تَصِحَّ، فَإِنَّهَا تُعَبِّرُ عَنْ صُورَتِهِ فِي الذَّاكِرَةِ الثَّقَافِيَّةِ: رَجُلٌ عَاشَ بَيْنَ الْكُتُبِ وَمَاتَ بَيْنَهَا.', 'Bu rivayet sahih olsun ya da olmasın, onun kültürel hafızadaki suretini ifade eder: kitaplar arasında yaşamış ve kitaplar arasında ölmüş bir adam.'],
  ['وَيَرَى الْبَاحِثُونَ الْمُعَاصِرُونَ فِيهِ نَمُوذَجًا لِلْمُثَقَّفِ الْمَوْسُوعِيِّ الَّذِي يَجْمَعُ بَيْنَ الْعِلْمِ وَالْفُكَاهَةِ وَالنَّقْدِ الِاجْتِمَاعِيِّ.', 'Çağdaş araştırmacılar onda ilmi, mizahı ve toplumsal eleştiriyi bir araya getiren ansiklopedik aydının bir örneğini görür.'],
  ['وَمَنْ أَرَادَ أَنْ يَخْتَبِرَ عَرَبِيَّتَهُ فِي مُسْتَوًى عَالٍ، فَلْيَقْرَأْ صَفْحَةً مِنَ الْجَاحِظِ كُلَّ يَوْمٍ؛ فَإِنَّهُ يَجْمَعُ صُعُوبَةَ الْأُسْلُوبِ وَمُتْعَةَ الْمَضْمُونِ.', 'Arapçasını yüksek bir seviyede sınamak isteyen, her gün Câhiz’den bir sayfa okusun; çünkü o, üslubun zorluğunu ve muhtevanın lezzetini birleştirir.']]],
 [V('اكْتَرَى – يَكْتَرِي', 'kiraladı', 'اكْتَرَى دُكَّانًا فِي السُّوقِ.', 'Çarşıda bir dükkân kiraladı.'),
  V('الْوَرَّاقُ (ج. الْوَرَّاقُونَ)', 'kitapçı, kitap istinsahçısı', 'كَانَ الْوَرَّاقُونَ يَنْسَخُونَ الْكُتُبَ وَيَبِيعُونَهَا.', 'Verrâklar kitapları istinsah edip satarlardı.'),
  V('الِاحْتِكَامُ إِلَى', '-e başvurma, -i hakem kılma', 'الِاحْتِكَامُ إِلَى الْعَقْلِ مِنْ مَنْهَجِ الْمُعْتَزِلَةِ.', 'Akla başvurmak Mu‘tezile’nin yöntemindendir.'),
  V('قِنَاعٌ', 'peçe, maske', 'كَشَفَ الْبَيَانُ قِنَاعَ الْمَعْنَى.', 'Beyân anlamın peçesini açtı.'),
  V('نَادِرَةٌ (ج. نَوَادِرُ)', 'nükte, ilginç fıkra', 'يَحْكِي الْجَاحِظُ نَوَادِرَ الْبُخَلَاءِ.', 'Câhiz cimrilerin nüktelerini anlatır.'),
  V('الِاسْتِطْرَادُ', 'istitrat, konudan konuya geçme', 'يُكْثِرُ الْكَاتِبُ مِنَ الِاسْتِطْرَادِ.', 'Yazar sık sık konu dışına çıkar.'),
  V('الْمَلَلُ', 'usanç, bıkkınlık', 'قَطَعَ الْحَدِيثَ دَفْعًا لِلْمَلَلِ.', 'Usancı gidermek için konuşmayı kesti.'),
  V('مَفْلُوجٌ', 'felçli', 'عَاشَ آخِرَ عُمُرِهِ مَفْلُوجًا.', 'Ömrünün sonunu felçli olarak geçirdi.')],
 [['Câhiz hangi itikadî ekole mensuptu?', ['Eş‘ariyye', 'Mu‘tezile', 'Mâtürîdiyye', 'Zâhiriyye'], 1],
  ['Câhiz beyânı nasıl tanımlar?', ['Yalnızca güzel söz', 'Anlamın peçesini açan her şeyin ortak adı', 'Şiir vezni', 'Kur’an’ın i‘câzı'], 1],
  ['Câhiz istitradı neden yaptığını söyler?', ['Kitabı uzatmak için', 'Okurdan usancı gidermek için', 'Hocasını taklit için', 'Sansürden kaçmak için'], 1],
  ['Hangisi Câhiz’in eseri değildir?', ['el-Hayevân', 'el-Buhalâ', 'el-Beyân ve’t-tebyîn', 'Delâilü’l-i‘câz'], 3]]))

X.append(L('I', 7, 'الْمُعَلَّقَاتُ بَيْنَ الرِّوَايَةِ وَالنَّقْدِ', 'Muallakalar: rivayet ile eleştiri arasında', [
 [['الْمُعَلَّقَاتُ قَصَائِدُ طِوَالٌ مِنَ الشِّعْرِ الْجَاهِلِيِّ، اخْتَارَهَا الرُّوَاةُ مِنْ بَيْنِ آلَافِ الْقَصَائِدِ، وَعَدُّوهَا أَجْوَدَ مَا قَالَتْهُ الْعَرَبُ قَبْلَ الْإِسْلَامِ.', 'Muallakalar, ravilerin binlerce kaside arasından seçtiği ve Arapların İslâm’dan önce söylediklerinin en iyisi saydığı uzun Câhiliye kasideleridir.'],
  ['وَأَشْهَرُ الرِّوَايَاتِ أَنَّهَا سَبْعٌ، لِامْرِئِ الْقَيْسِ وَطَرَفَةَ وَزُهَيْرٍ وَلَبِيدٍ وَعَمْرِو بْنِ كُلْثُومٍ وَعَنْتَرَةَ وَالْحَارِثِ بْنِ حِلِّزَةَ، وَزَادَ بَعْضُهُمْ ثَلَاثًا فَجَعَلَهَا عَشْرًا.', 'En meşhur rivayete göre bunlar yedidir: İmruülkays, Tarafe, Züheyr, Lebîd, Amr b. Külsûm, Antere ve Hâris b. Hillize’nin kasideleri; bazıları üç tane daha ekleyip onları ona çıkarmıştır.'],
  ['وَيُنْسَبُ جَمْعُهَا إِلَى حَمَّادٍ الرَّاوِيَةِ فِي أَوَاخِرِ الْعَصْرِ الْأُمَوِيِّ، أَيْ بَعْدَ نَظْمِهَا بِزَمَنٍ طَوِيلٍ.', 'Bunların derlenmesi Emevî devrinin sonlarında, yani söylenişlerinden uzun zaman sonra Hammâd er-Râviye’ye nispet edilir.'],
  ['أَمَّا اسْمُهَا فَقَدْ قِيلَ إِنَّهَا كُتِبَتْ بِمَاءِ الذَّهَبِ وَعُلِّقَتْ عَلَى أَسْتَارِ الْكَعْبَةِ، غَيْرَ أَنَّ كَثِيرًا مِنَ الْعُلَمَاءِ قُدَمَاءَ وَمُحْدَثِينَ شَكَّكُوا فِي هَذِهِ الرِّوَايَةِ.', 'Adına gelince, altın suyuyla yazılıp Kâbe’nin örtülerine asıldığı söylenmiştir; ancak eski ve yeni pek çok âlim bu rivayetten şüphe etmiştir.']],
 [['وَيَرَى بَعْضُهُمْ أَنَّهَا سُمِّيَتْ بِذَلِكَ لِأَنَّهَا عُلِّقَتْ فِي الْأَذْهَانِ لِجَوْدَتِهَا، أَوْ لِأَنَّهَا تُشْبِهُ الْعُقُودَ النَّفِيسَةَ الْمُعَلَّقَةَ فِي الْأَعْنَاقِ؛ وَلِذَلِكَ سُمِّيَتْ أَيْضًا «السُّمُوطَ» وَ«الْمُذَهَّبَاتِ».', 'Bazıları, güzelliklerinden ötürü zihinlere asıldıkları ya da boyunlara asılan değerli gerdanlıklara benzedikleri için bu adı aldıklarını düşünür; bu yüzden onlara “es-Sumût” (gerdanlıklar) ve “el-Müzehhebât” (altınlanmışlar) da denmiştir.'],
  ['وَتَتْبَعُ أَكْثَرُ هَذِهِ الْقَصَائِدِ بِنَاءً مُتَقَارِبًا: تَبْدَأُ بِالْوُقُوفِ عَلَى الْأَطْلَالِ، ثُمَّ تَنْتَقِلُ إِلَى وَصْفِ الرِّحْلَةِ وَالنَّاقَةِ، ثُمَّ تَصِلُ إِلَى غَرَضِ الشَّاعِرِ مِنْ فَخْرٍ أَوْ مَدْحٍ أَوْ حِكْمَةٍ.', 'Bu kasidelerin çoğu birbirine yakın bir yapı izler: Harabeler (atlâl) başında durmakla başlar, sonra yolculuğun ve devenin tasvirine geçer, sonra şairin övünme, övgü ya da hikmet gibi asıl amacına varır.'],
  ['وَأَشْهَرُ مَطْلَعٍ فِي الشِّعْرِ الْعَرَبِيِّ قَوْلُ امْرِئِ الْقَيْسِ: «قِفَا نَبْكِ مِنْ ذِكْرَى حَبِيبٍ وَمَنْزِلِ».', 'Arap şiirinin en meşhur matla‘ı İmruülkays’ın şu sözüdür: “Durun da bir sevgilinin ve bir konağın hatırasına ağlayalım.”'],
  ['أَمَّا زُهَيْرٌ فَخَتَمَ مُعَلَّقَتَهُ بِأَبْيَاتٍ فِي الْحِكْمَةِ، مِنْهَا: «وَمَهْمَا تَكُنْ عِنْدَ امْرِئٍ مِنْ خَلِيقَةٍ ... وَإِنْ خَالَهَا تَخْفَى عَلَى النَّاسِ تُعْلَمِ».', 'Züheyr ise muallakasını hikmet beyitleriyle bitirdi; bunlardan biri şudur: “Kişide hangi huy bulunursa, insanlardan gizli kalacağını sansa da bilinir.”']],
 [['وَلِلْمُعَلَّقَاتِ مَنْزِلَةٌ خَاصَّةٌ عِنْدَ عُلَمَاءِ الْإِسْلَامِ، لِأَنَّهَا مِنْ أَهَمِّ الشَّوَاهِدِ عَلَى لُغَةِ الْعَرَبِ الَّتِي نَزَلَ بِهَا الْقُرْآنُ.', 'Muallakaların İslâm âlimleri nezdinde özel bir yeri vardır; çünkü onlar Kur’an’ın indiği Arap dilinin en önemli şahitlerindendir.'],
  ['وَيُنْسَبُ إِلَى ابْنِ عَبَّاسٍ قَوْلُهُ: «الشِّعْرُ دِيوَانُ الْعَرَبِ؛ فَإِذَا خَفِيَ عَلَيْنَا الْحَرْفُ مِنَ الْقُرْآنِ رَجَعْنَا إِلَى دِيوَانِهَا».', 'İbn Abbâs’a şu söz nispet edilir: “Şiir Arapların divanıdır; Kur’an’dan bir kelime bize kapalı kalırsa onların divanına başvururuz.”'],
  ['وَلِذَلِكَ كَثُرَتْ شُرُوحُهَا، وَمِنْ أَشْهَرِهَا شَرْحُ الزَّوْزَنِيِّ وَشَرْحُ التِّبْرِيزِيِّ، وَمَا زَالَا يُدَرَّسَانِ فِي أَقْسَامِ اللُّغَةِ الْعَرَبِيَّةِ إِلَى الْيَوْمِ.', 'Bu yüzden şerhleri çoğaldı; en meşhurları Zevzenî’nin ve Tebrîzî’nin şerhleridir ve her ikisi de bugün hâlâ Arap dili bölümlerinde okutulmaktadır.'],
  ['وَأَسْلَمَ لَبِيدٌ، وَتَذْكُرُ الرِّوَايَاتُ أَنَّهُ قَلَّ قَوْلُهُ لِلشِّعْرِ بَعْدَ إِسْلَامِهِ، فَكَأَنَّ الْقُرْآنَ أَغْنَاهُ عَنِ الْقَوْلِ.', 'Lebîd Müslüman oldu; rivayetler onun Müslüman olduktan sonra pek az şiir söylediğini anlatır; sanki Kur’an onu söz söylemekten müstağni kılmıştı.']],
 [['وَفِي الْعَصْرِ الْحَدِيثِ أَثَارَ الْمُسْتَشْرِقُ مَرْجِلْيُوثُ، ثُمَّ طَهَ حُسَيْنٌ فِي كِتَابِهِ «فِي الشِّعْرِ الْجَاهِلِيِّ» سَنَةَ أَلْفٍ وَتِسْعِ مِئَةٍ وَسِتٍّ وَعِشْرِينَ، شُكُوكًا فِي صِحَّةِ كَثِيرٍ مِنْ هَذَا الشِّعْرِ.', 'Modern dönemde müsteşrik Margoliouth, ardından Tâhâ Hüseyin 1926’da “Fi’ş-şi‘ri’l-câhilî” adlı kitabında bu şiirin büyük kısmının sıhhati hakkında şüpheler ortaya attı.'],
  ['وَرَأَى طَهَ حُسَيْنٌ أَنَّ كَثِيرًا مِنْهُ وُضِعَ بَعْدَ الْإِسْلَامِ لِأَسْبَابٍ سِيَاسِيَّةٍ وَدِينِيَّةٍ وَقَبَلِيَّةٍ، وَاسْتَدَلَّ بِأَنَّهُ لَا يَعْكِسُ اخْتِلَافَ لَهَجَاتِ الْقَبَائِلِ.', 'Tâhâ Hüseyin bunun önemli bir kısmının İslâm’dan sonra siyasi, dinî ve kabilevî sebeplerle uydurulduğunu düşündü ve kabile lehçelerinin farklılığını yansıtmamasını delil gösterdi.'],
  ['فَرَدَّ عَلَيْهِ عُلَمَاءُ كَثِيرُونَ، وَبَيَّنُوا أَنَّ الشُّعَرَاءَ كَانُوا يَنْظِمُونَ بِلُغَةٍ أَدَبِيَّةٍ مُشْتَرَكَةٍ فَوْقَ اللَّهَجَاتِ، وَأَنَّ نُقَّادَ الْعَرَبِ الْقُدَمَاءَ قَدْ مَيَّزُوا الْمَنْحُولَ مِنَ الصَّحِيحِ.', 'Birçok âlim ona cevap verdi; şairlerin lehçelerin üstünde ortak bir edebî dille şiir söylediğini ve eski Arap eleştirmenlerinin uydurmayı sahihten ayırdığını gösterdiler.'],
  ['وَهَكَذَا صَارَتِ الْمُعَلَّقَاتُ مَيْدَانًا لِسُؤَالٍ أَكْبَرَ: كَيْفَ نَثِقُ بِنَصٍّ وَصَلَ إِلَيْنَا بِالرِّوَايَةِ الشَّفَهِيَّةِ؟ وَهُوَ سُؤَالٌ يَعْرِفُهُ دَارِسُ الْحَدِيثِ أَيْضًا.', 'Böylece Muallakalar daha büyük bir sorunun alanı oldu: Bize sözlü rivayetle ulaşan bir metne nasıl güveniriz? Bu, hadis öğrencisinin de bildiği bir sorudur.']]],
 [V('الْأَطْلَالُ', 'harabeler, yurt kalıntıları', 'وَقَفَ الشَّاعِرُ عَلَى الْأَطْلَالِ يَبْكِي.', 'Şair harabelerin başında durup ağladı.'),
  V('الرُّوَاةُ (مُفْرَدُهُ رَاوِيَةٌ / رَاوٍ)', 'raviler, şiir nakledenler', 'حَفِظَ الرُّوَاةُ الشِّعْرَ الْجَاهِلِيَّ.', 'Raviler Câhiliye şiirini ezberleyip korudu.'),
  V('شَكَّكَ فِي', '-den şüphe etti, kuşku düşürdü', 'شَكَّكَ الْبَاحِثُ فِي صِحَّةِ الرِّوَايَةِ.', 'Araştırmacı rivayetin sıhhatinden şüphe etti.'),
  V('مَطْلَعٌ', 'matla‘, kasidenin ilk beyti', 'حَفِظْتُ مَطْلَعَ الْقَصِيدَةِ.', 'Kasidenin matla‘ını ezberledim.'),
  V('خَلِيقَةٌ', 'huy, tabiat', 'لِكُلِّ امْرِئٍ خَلِيقَةٌ تَظْهَرُ يَوْمًا.', 'Her insanın bir gün ortaya çıkan bir huyu vardır.'),
  V('شَاهِدٌ (ج. شَوَاهِدُ)', 'şahit; dilde delil olarak getirilen söz', 'اسْتَشْهَدَ النُّحَاةُ بِهَذَا الْبَيْتِ.', 'Nahivciler bu beyti delil olarak getirdi.'),
  V('مَنْحُولٌ', 'uydurma, başkasına nispet edilmiş', 'مَيَّزَ النُّقَّادُ الشِّعْرَ الْمَنْحُولَ.', 'Eleştirmenler uydurma şiiri ayırt ettiler.'),
  V('شَفَهِيٌّ', 'sözlü', 'انْتَقَلَ الشِّعْرُ بِالرِّوَايَةِ الشَّفَهِيَّةِ.', 'Şiir sözlü rivayetle aktarıldı.')],
 [['Muallakaların derlenmesi kime nispet edilir?', ['Halîl b. Ahmed', 'Hammâd er-Râviye', 'Zevzenî', 'İbn Abbâs'], 1],
  ['Muallakaların Kâbe’ye asıldığı rivayeti hakkında metin ne der?', ['Kesin olarak doğrudur', 'Birçok âlim bundan şüphe etmiştir', 'Kur’an’da geçer', 'Hiç kimse bunu söylememiştir'], 1],
  ['Muallakaların tipik yapısı hangi bölümle başlar?', ['Övgü (medih)', 'Atlâl (harabeler) başında durmak', 'Hiciv', 'Dua'], 1],
  ['Tâhâ Hüseyin’e cevap verenlere göre şairler hangi dille şiir söylerdi?', ['Kendi kabile lehçeleriyle', 'Lehçelerin üstünde ortak bir edebî dille', 'Süryanice', 'Yalnızca Kureyş lehçesiyle'], 1]]))
